mapper.select:
SELECT EXISTS (
  SELECT 1
  FROM workflow_tasks
  WHERE workflow_instance_id = #{workflowInstanceId, jdbcType=OTHER}
    AND task_key = #{taskKey}
    AND status = 'PENDING'
)

mapper.update:
UPDATE workflow_tasks
SET status = 'COMPLETED', completed_by = #{completedBy, jdbcType=OTHER}, completed_at = #{completedAt}
WHERE id = #{id, jdbcType=OTHER} AND status = 'PENDING'
